package megalodonte.engine.editor;
import javafx.collections.*;
import javafx.scene.control.*;
import javafx.scene.control.cell.TextFieldTableCell;
import javafx.scene.layout.*;
import javafx.stage.Window;
import megalodonte.engine.*;
import java.util.*;
import java.util.function.*;

/** Structured editors for portable fields that formerly required hand-editing JSON. */
final class FeatureForms {
    static final class Form {
        final VBox box=new VBox(6);final Map<String,TextField> fields=new LinkedHashMap<>();final Map<String,CheckBox> checks=new LinkedHashMap<>();
        TextField text(String key,String label,Object value){var input=new TextField(""+value);input.setId(key);fields.put(key,input);box.getChildren().addAll(new Label(label),input);return input;}
        CheckBox check(String key,String label,boolean value){var input=new CheckBox(label);input.setId(key);input.setSelected(value);checks.put(key,input);box.getChildren().add(input);return input;}
        String value(String key){return fields.get(key).getText().strip();}double number(String key){return Double.parseDouble(value(key));}boolean flag(String key){return checks.get(key).isSelected();}
    }
    static void dialog(Window owner,String title,javafx.scene.Node content,Runnable apply){
        var d=new Dialog<Void>();d.initOwner(owner);d.setTitle(title);d.getDialogPane().getButtonTypes().addAll(ButtonType.APPLY,ButtonType.CLOSE);((Button)d.getDialogPane().lookupButton(ButtonType.APPLY)).setText("Aplicar");((Button)d.getDialogPane().lookupButton(ButtonType.CLOSE)).setText("Fechar");var error=new Label();error.setWrapText(true);var scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefViewportHeight(510);scroll.setPrefViewportWidth(530);d.getDialogPane().setContent(new VBox(10,scroll,error));
        d.getDialogPane().lookupButton(ButtonType.APPLY).addEventFilter(javafx.event.ActionEvent.ACTION,e->{e.consume();try{apply.run();error.setText("Aplicado. Salve o projeto para persistir.");}catch(Exception failure){error.setText("Não aplicado: "+failure.getMessage());}});d.show();
    }
    static void entity(Window owner,Game.Entity target,Consumer<Game.Entity> apply){
        var f=new Form();f.text("entityId","ID usado pelos scripts",target.id);f.text("entityAsset","Sprite estático (caminho relativo)",target.assetPath);f.check("entityVisible","Visível",target.visible);f.check("entityFlip","Espelhar horizontalmente",target.flipX);f.check("colliderFlip","Espelhar colisor junto com o sprite",target.colliderFollowsFlip);f.check("entitySolid","Colisor ativado",target.solid);f.check("entityTrigger","Gatilho: detecta contato sem bloquear movimento",target.trigger);f.check("entityPlayer","Controlável pelas direções padrão",target.player);
        f.text("colliderX","Colisor: deslocamento X",target.colliderOffsetX);f.text("colliderY","Colisor: deslocamento Y",target.colliderOffsetY);f.text("colliderWidth","Colisor: largura (0 = sprite)",target.colliderWidth);f.text("colliderHeight","Colisor: altura (0 = sprite)",target.colliderHeight);
        f.text("drawLayer","Camada de desenho (menor = fundo)",target.drawLayer);f.text("colliderPolygon","Polígono local: x,y,x,y… (vazio = retângulo)",target.colliderPolygon.toString().replace("[","").replace("]",""));
        f.text("animationClock","Tempo inicial da animação (segundos)",target.animationTime);var animation=new ComboBox<String>();animation.getItems().add("");animation.getItems().addAll(target.animations.keySet());animation.setValue(target.animation);f.box.getChildren().addAll(new Label("Animação inicial (vazio = sprite estático)"),animation);
        f.box.getChildren().add(new Label("Ao mudar o ID, atualize referências escritas nos scripts."));var props=properties(target.properties);f.box.getChildren().addAll(new Label("Propriedades para scripts"),props.box);
        dialog(owner,"Objeto • colisor e propriedades",f.box,()->{var copy=target.copy();copy.id=f.value("entityId");copy.assetPath=f.value("entityAsset");copy.visible=f.flag("entityVisible");copy.flipX=f.flag("entityFlip");copy.colliderFollowsFlip=f.flag("colliderFlip");copy.solid=f.flag("entitySolid");copy.trigger=f.flag("entityTrigger");copy.player=f.flag("entityPlayer");copy.colliderOffsetX=f.number("colliderX");copy.colliderOffsetY=f.number("colliderY");copy.colliderWidth=f.number("colliderWidth");copy.colliderHeight=f.number("colliderHeight");copy.drawLayer=Integer.parseInt(f.value("drawLayer"));copy.colliderPolygon=polygon(f.value("colliderPolygon"));copy.animationTime=f.number("animationClock");copy.animation=animation.getValue();copy.properties=props.values();apply.accept(copy);});
    }
    static java.util.List<Double> polygon(String text){var values=new java.util.ArrayList<Double>();if(!text.isBlank())for(String value:text.split("[,;\\s]+"))values.add(Double.parseDouble(value));CollisionGeometry.validate(values);return values;}
    static final class Pair {String key,value;Pair(String key,String value){this.key=key;this.value=value;}}
    static final class Properties {
        final TableView<Pair> table=new TableView<>();final VBox box;
        Properties(Map<String,String> values){table.setEditable(true);table.setPrefHeight(180);table.getItems().setAll(values.entrySet().stream().map(e->new Pair(e.getKey(),e.getValue())).toList());
            var key=new TableColumn<Pair,String>("Chave");key.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().key));key.setCellFactory(column->new TextFieldTableCell<Pair,String>(new javafx.util.converter.DefaultStringConverter()){@Override public void startEdit(){super.startEdit();if(getGraphic() instanceof TextField input)input.focusedProperty().addListener((o,a,focused)->{if(!focused&&isEditing())commitEdit(input.getText());});}});key.setOnEditCommit(e->e.getRowValue().key=e.getNewValue());key.setPrefWidth(180);
            var value=new TableColumn<Pair,String>("Valor");value.setCellValueFactory(c->new javafx.beans.property.SimpleStringProperty(c.getValue().value));value.setCellFactory(column->new TextFieldTableCell<Pair,String>(new javafx.util.converter.DefaultStringConverter()){@Override public void startEdit(){super.startEdit();if(getGraphic() instanceof TextField input)input.focusedProperty().addListener((o,a,focused)->{if(!focused&&isEditing())commitEdit(input.getText());});}});value.setOnEditCommit(e->e.getRowValue().value=e.getNewValue());value.setPrefWidth(240);table.getColumns().add(key);table.getColumns().add(value);
            var add=new Button("Adicionar propriedade");add.setOnAction(e->table.getItems().add(new Pair("nova","")));var remove=new Button("Excluir propriedade");remove.setOnAction(e->table.getItems().remove(table.getSelectionModel().getSelectedItem()));box=new VBox(6,table,new HBox(8,add,remove));}
        Map<String,String> values(){var result=new LinkedHashMap<String,String>();for(var p:table.getItems()){String key=p.key.strip();if(key.isBlank()||result.putIfAbsent(key,p.value)!=null)throw new IllegalArgumentException("Chaves devem ser preenchidas e únicas.");}return result;}
    }
    static Properties properties(Map<String,String> values){return new Properties(values);}
    static void project(Window owner,Game game,Consumer<Game> apply){var f=new Form();f.text("gameName","Nome do jogo",game.name);f.text("applicationId","Identificador Android / aplicativo",game.applicationId);f.text("versionCode","Código da versão Android (inteiro crescente)",game.versionCode);f.text("versionName","Versão exibida (ex.: 1.0.0)",game.versionName);f.text("iconAssetPath","Ícone do aplicativo (asset PNG relativo)",game.iconAssetPath);var initial=new ComboBox<Game.Scene>(FXCollections.observableArrayList(game.scenes));initial.setConverter(new javafx.util.StringConverter<>(){public String toString(Game.Scene s){return s==null?"":s.name;}public Game.Scene fromString(String s){return null;}});initial.setValue(game.scenes.stream().filter(s->s.id.equals(game.entrySceneId)).findFirst().orElseThrow());f.box.getChildren().addAll(new Label("Cena inicial"),initial);
        dialog(owner,"Projeto",f.box,()->{var copy=Codec.copy(game);copy.versionCode=Integer.parseInt(f.value("versionCode"));copy.versionName=f.value("versionName");copy.iconAssetPath=f.value("iconAssetPath");copy.name=f.value("gameName");copy.applicationId=f.value("applicationId");copy.entrySceneId=initial.getValue().id;Codec.validate(copy);apply.accept(copy);});}
    static void scene(Window owner,Game.Scene scene,Consumer<Game.Scene> apply){var f=new Form();f.text("sceneId","ID da cena",scene.id);f.text("sceneName","Nome",scene.name);f.text("sceneBackground","Cor do fundo (#RRGGBB)",scene.background);f.text("backgroundAsset","Imagem do fundo (asset relativo)",scene.backgroundAssetPath);f.text("backgroundParallax","Paralaxe horizontal do fundo (0–1)",scene.backgroundParallaxX);f.check("musicLoop","Repetir música",scene.musicLoop);f.check("depthSort","Ordenar objetos por profundidade (isométrico)",scene.depthSort);f.check("cameraClamp","Limitar câmera ao mundo",scene.camera.clampToWorld);f.check("cameraHoldGround","Manter chão enquadrado durante saltos",scene.camera.holdGroundDuringJump);
        f.text("cameraFollowOffsetX","Deslocamento X do alvo da câmera (unidades do mundo)",scene.camera.followOffsetX);f.text("cameraFollowOffsetY","Deslocamento Y do alvo da câmera (positivo enquadra mais acima)",scene.camera.followOffsetY);f.text("cameraViewportTop","Faixa superior reservada à HUD (0–719)",scene.camera.viewportTop);f.text("sceneMusicPath","Asset de música (caminho relativo)",scene.musicAssetPath);f.text("cameraTarget","ID do objeto seguido",scene.camera.targetId);var targets=new ComboBox<Game.Entity>();var none=new Game.Entity();none.id="";none.name="Nenhum";targets.getItems().add(none);targets.getItems().addAll(scene.objects);targets.setConverter(new javafx.util.StringConverter<>(){public String toString(Game.Entity e){return e==null?"Nenhum":e.name;}public Game.Entity fromString(String s){return null;}});targets.setValue(scene.objects.stream().filter(e->e.id.equals(scene.camera.targetId)).findFirst().orElse(none));targets.setOnAction(e->f.fields.get("cameraTarget").setText(targets.getValue()==null?"":targets.getValue().id));f.box.getChildren().addAll(new Label("Escolher objeto seguido"),targets);
        var mode=new ComboBox<String>(FXCollections.observableArrayList("fixed","follow"));mode.setValue(scene.camera.mode);f.box.getChildren().addAll(new Label("Modo da câmera"),mode);
        dialog(owner,"Cena • identificação e opções",f.box,()->{var copy=Codec.GSON.fromJson(Codec.GSON.toJson(scene),Game.Scene.class);copy.id=f.value("sceneId");copy.name=f.value("sceneName");copy.background=f.value("sceneBackground");copy.backgroundAssetPath=f.value("backgroundAsset");copy.backgroundParallaxX=f.number("backgroundParallax");copy.musicLoop=f.flag("musicLoop");copy.depthSort=f.flag("depthSort");copy.musicAssetPath=f.value("sceneMusicPath");copy.camera.followOffsetX=f.number("cameraFollowOffsetX");copy.camera.followOffsetY=f.number("cameraFollowOffsetY");copy.camera.clampToWorld=f.flag("cameraClamp");copy.camera.holdGroundDuringJump=f.flag("cameraHoldGround");copy.camera.viewportTop=Double.parseDouble(f.value("cameraViewportTop"));copy.camera.mode=mode.getValue();copy.camera.targetId=f.value("cameraTarget");apply.accept(copy);});}
    static void hud(Window owner,Game.Hud hud,Consumer<Game.Hud> apply){
        var f=new Form();f.check("hudVisible","Visível ao iniciar o jogo",hud.visible);f.text("hudAsset","Imagem padrão (caminho relativo)",hud.assetPath);f.text("hudButtonBackground","Cor de fundo do botão",hud.buttonBackground);f.text("hudButtonOpacity","Opacidade do fundo (0–1)",hud.buttonOpacity);f.text("hudCornerRadius","Raio dos cantos",hud.cornerRadius);f.text("hudFontFamily","Família da fonte (vazio = padrão)",hud.fontFamily);f.text("hudTextAlign","Alinhamento do texto: left / center / right",hud.textAlign);f.text("hudTextVerticalAlign","Alinhamento vertical: top / center / bottom",hud.textVerticalAlign);var type=new ComboBox<String>(FXCollections.observableArrayList("text","image","button"));type.setValue(hud.type);f.box.getChildren().addAll(new Label("Tipo"),type);
        var properties=new HudPropertiesForm(hud.properties);var c=new Form();c.text("hudConditionProperty","Propriedade booleana (vazio = sem condição)",hud.condition.property);c.text("hudTrueAsset","Imagem quando true (vazio = padrão)",hud.condition.trueAssetPath);c.text("hudFalseAsset","Imagem quando false (vazio = padrão)",hud.condition.falseAssetPath);c.check("hudDisableFalse","Bloquear clique quando false",hud.condition.disableWhenFalse);c.box.getChildren().add(new Label("A prévia usa os valores iniciais. O script pode alterá-los durante o jogo."));
        var tabs=new TabPane(new Tab("Opções",f.box),new Tab("Propriedades",properties.box),new Tab("Condição visual",c.box));tabs.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);tabs.setId("hudFeaturesTabs");tabs.getSelectionModel().select(hud.properties.isEmpty()?0:1);
        dialog(owner,"HUD • propriedades e condições",tabs,()->{var copy=hud.copy();copy.visible=f.flag("hudVisible");copy.assetPath=f.value("hudAsset");copy.type=type.getValue();copy.buttonBackground=f.value("hudButtonBackground");copy.buttonOpacity=f.number("hudButtonOpacity");copy.cornerRadius=f.number("hudCornerRadius");copy.fontFamily=f.value("hudFontFamily");copy.textAlign=f.value("hudTextAlign");copy.textVerticalAlign=f.value("hudTextVerticalAlign");copy.properties=properties.values();copy.condition.property=c.value("hudConditionProperty");copy.condition.trueAssetPath=c.value("hudTrueAsset");copy.condition.falseAssetPath=c.value("hudFalseAsset");copy.condition.disableWhenFalse=c.flag("hudDisableFalse");HudPresentation.validate(copy);apply.accept(copy);});
    }
}
